/**
 * Hr's own strings, in every locale the platform ships.
 *
 * Data only, and deliberately so: this module imports nothing but a type, which is what lets a test
 * load the bundles and check them. `i18n.ts` next door pulls in `@kernhq/ui` for `scopedT`, and
 * that entry point reaches the Svelte components — so anything importing it drags a compiler into
 * whatever is doing the importing. Keys, plural forms and placeholders are checkable facts; keeping
 * them behind that import made them uncheckable.
 *
 * A value may be a plural form set rather than a string. `t()` picks the CLDR category for the
 * reader's locale from the `count` (or `n`) parameter, so a counted message must spell its
 * placeholder `{count}` — `{days}` renders but never selects, which is how "1 days" ships.
 */
